<?php
require_once __DIR__.'/../../includes/layout.php';require_login();check_csrf();$error='';$u=current_user();$staff=campus_staff();$id=(int)($_GET['id']??0);$claimId=(int)($_GET['claim']??0);
if($_SERVER['REQUEST_METHOD']==='POST')try{
 $action=(string)($_POST['action']??'');
 if($action==='report'){$id=lf_report($_POST);$claimId=0;}
 elseif($action==='claim'){$claimId=lf_submit_claim($id,(string)($_POST['proof']??''));}
 elseif($claimId)lf_update_claim($claimId,$_POST);else lf_moderate($id,$_POST);
 set_flash('success','Lost-and-found update saved.');redirect('lost_found.php?'.($claimId?'claim='.$claimId:'id='.$id));
}catch(InvalidArgumentException $e){$error=$e->getMessage();}
$claim=$claimId?lf_claim($claimId):null;if($claimId&&!$claim){http_response_code(404);exit('Claim not found.');}
$private=$id?lf_private_item($id):null;$item=$id?($private?:lf_public_item($id)):null;if($id&&!$item){http_response_code(404);exit('Report not found.');}
render_header('Lost and found'); ?>
<div class="page-title"><div><span class="eyebrow">CAMPUS COMMUNITY</span><h1>Lost and found</h1><p>Report missing or found belongings. Ownership evidence stays private, and the school verifies claims before release.</p></div><a class="btn btn-outline-primary" href="lost_found.php">Listings & my reports</a></div>
<?php if($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?>
<?php if($claim): ?>
<section class="panel"><h2>Ownership claim · <?= e($claim['title']) ?></h2><p><strong><?= e($claim['state']) ?></strong></p><p class="small text-muted">Claim evidence and review history are visible only to the claimant and authorized Admin/Super Admin staff.</p><p>Claimant: <?= e($claim['claimant']) ?></p><h3>Private ownership evidence</h3><p class="campus-preserve"><?= e($claim['proof']) ?></p><?php if($claim['staff_note']): ?><h3>Office feedback</h3><p class="campus-preserve"><?= e($claim['staff_note']) ?></p><?php endif; ?></section>
<?php if((int)$claim['owner_id']===(int)$u['id']&&$claim['state']==='Needs information'): ?><section class="panel"><h2>Provide more information</h2><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="resubmit"><input type="hidden" name="revision" value="<?= (int)$claim['revision'] ?>"><label>Corrected private evidence<textarea name="proof" class="form-control" rows="4" minlength="10" maxlength="1500" required><?= e($claim['proof']) ?></textarea></label><button class="btn btn-primary">Resubmit private evidence</button></form></section><?php endif; ?>
<?php if($staff&&(int)$claim['owner_id']!==(int)$u['id']&&in_array($claim['state'],['Pending','Needs information','Verified'],true)): ?><section class="panel"><h2>Office claim verification</h2><p>Compare the evidence with the item's private details and inspect the actual item. Verify the recipient in person before handover.</p><a href="?id=<?= (int)$claim['item_id'] ?>">Open private item record →</a><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="review"><input type="hidden" name="revision" value="<?= (int)$claim['revision'] ?>"><label for="lf-decision">Decision</label><select id="lf-decision" name="state" class="form-select" required><option value="">Choose decision</option><option value="Needs information">Request more information</option><option value="Verified">Verify ownership evidence</option><option value="Rejected">Reject claim</option><?php if($claim['state']==='Verified'): ?><option value="Released">Confirm item release</option><?php endif; ?></select><label>Review note for claimant<textarea name="note" class="form-control" minlength="5" maxlength="600" rows="3" required></textarea></label><label><input type="checkbox" name="confirm_handover" value="1"> I checked the recipient and completed the in-person handover (required for release).</label><button class="btn btn-primary">Save claim decision</button></form></section><?php endif; ?>
<?php if((int)$claim['owner_id']===(int)$u['id']&&in_array($claim['state'],['Pending','Needs information','Verified'],true)): ?><form method="post" class="panel"><?= csrf_field() ?><input type="hidden" name="revision" value="<?= (int)$claim['revision'] ?>"><p>Withdraw only if you no longer wish to pursue this claim. Contact the office if you need to reopen a closed claim.</p><button class="btn btn-outline-danger" name="action" value="withdraw">Withdraw my claim</button></form><?php endif; ?>
<section class="panel"><h2>Private claim history</h2><?php foreach(rows('SELECT e.*,u.full_name FROM lost_found_events e JOIN users u ON u.id=e.actor_id WHERE e.claim_id=? ORDER BY e.id',[$claimId]) as $event): ?><article class="campus-event"><strong><?= e($event['full_name']) ?></strong><p class="campus-preserve"><?= e($event['body']) ?></p><small><?= e(campus_time($event['created_at'])) ?></small></article><?php endforeach; ?></section>
<?php elseif($item): ?>
<section class="panel"><h2><?= e($item['title']) ?></h2><p><?= e($item['kind'].' · '.$item['category'].' · '.$item['item_date']) ?></p><p>Broad location: <?= e($item['location']) ?></p><p><?= e($item['listing_state'].' · '.$item['resolution']) ?></p>
<?php if($private): ?><h3>Private identifying details</h3><p class="campus-preserve"><?= e($private['private_details']) ?></p><p>Reporter: <?= e($private['reporter']) ?></p><?php endif; ?>
<?php if($staff&&$item['listing_state']==='Pending'&&$item['resolution']==='Open'): ?><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="publish"><input type="hidden" name="revision" value="<?= (int)$private['revision'] ?>"><h3>Moderate the public listing</h3><label>Generic public title<input name="title" class="form-control" value="<?= e($item['title']) ?>" minlength="3" maxlength="100" required></label><label>Broad public location<input name="location" class="form-control" value="<?= e($item['location']) ?>" minlength="2" maxlength="120" required></label><label><input type="checkbox" name="safe_publication" value="1" required> I reviewed these public fields and removed names, contact details, unique marks, ID numbers, and claim answers.</label><?php if($item['kind']==='Found'): ?><label><input type="checkbox" name="confirm_received" value="1" required> The school desk has received the found item.</label><?php endif; ?><button class="btn btn-primary">Publish safe listing</button></form><?php endif; ?>
<?php if($item['kind']==='Found'&&$item['listing_state']==='Published'&&$item['resolution']==='Open'&&(!$private||(int)$private['owner_id']!==(int)$u['id'])): ?><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="claim"><label>Private proof of ownership<textarea name="proof" class="form-control" minlength="10" maxlength="1500" rows="4" placeholder="Describe identifying marks, contents, or other evidence the office can verify. Never send passwords, PINs, or full ID numbers." required></textarea></label><p>This submits a private claim; it does not authorize collection.</p><button class="btn btn-primary">Submit ownership claim</button></form><?php endif; ?>
<?php if($private&&$item['kind']==='Lost'&&$item['resolution']==='Open'): ?><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="reunited"><input type="hidden" name="revision" value="<?= (int)$private['revision'] ?>"><label>Recovery note<textarea name="note" class="form-control" minlength="5" maxlength="600" required></textarea></label><button class="btn btn-outline-primary">I recovered this lost item</button></form><?php endif; ?>
<?php if($staff&&$item['listing_state']!=='Archived'): ?><details class="mt-3"><summary>Close this listing</summary><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="archive"><input type="hidden" name="revision" value="<?= (int)$private['revision'] ?>"><label>Private closure reason<textarea name="note" class="form-control" minlength="5" maxlength="600" required></textarea></label><button class="btn btn-outline-danger">Archive listing</button></form></details><?php endif; ?></section>
<?php if($staff): ?><section class="panel"><h2>Private ownership claims</h2><?php $claims=rows('SELECT c.id,c.state,u.full_name FROM lost_found_claims c JOIN users u ON u.id=c.owner_id WHERE c.item_id=? ORDER BY c.id',[$id]);if(!$claims)empty_state('No claims yet');foreach($claims as $c): ?><article class="campus-event"><a href="?claim=<?= (int)$c['id'] ?>"><?= e($c['full_name'].' · '.$c['state']) ?></a></article><?php endforeach; ?></section><?php endif; ?>
<?php if($private): ?><section class="panel"><h2>Report history</h2><?php foreach(rows('SELECT e.*,u.full_name FROM lost_found_events e JOIN users u ON u.id=e.actor_id WHERE e.item_id=? AND e.claim_id IS NULL ORDER BY e.id',[$id]) as $event): ?><article class="campus-event"><strong><?= e($event['full_name']) ?></strong><p><?= e($event['body']) ?></p><small><?= e(campus_time($event['created_at'])) ?></small></article><?php endforeach; ?></section><?php endif; ?>
<?php else:
 $q=trim((string)($_GET['q']??''));$kind=(string)($_GET['kind']??'');$category=(string)($_GET['category']??'');$after=(string)($_GET['after']??'');$before=(string)($_GET['before']??'');$where=['listing_state="Published"','resolution="Open"'];$params=[];
 if($q!==''){$where[]='(title LIKE ? OR location LIKE ?)';$params[]='%'.substr($q,0,120).'%';$params[]='%'.substr($q,0,120).'%';}if(in_array($kind,['Lost','Found'],true)){$where[]='kind=?';$params[]=$kind;}if(in_array($category,LOST_FOUND_CATEGORIES,true)){$where[]='category=?';$params[]=$category;}
 foreach(['after'=>$after,'before'=>$before] as $field=>$date)if($date!==''){$d=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if($d&&$d->format('Y-m-d')===$date){$where[]='item_date'.($field==='after'?'>=':'<=').'?';$params[]=$date;}}
 $listings=rows('SELECT id,title,kind,category,location,item_date FROM lost_found_items WHERE '.implode(' AND ',$where).' ORDER BY item_date DESC,id DESC LIMIT 100',$params);
 ?>
<div class="row g-4"><div class="col-lg-5"><section class="panel"><h2>Report an item</h2><p>Use a generic title and broad location. Put identifying marks only in the private details. Staff review reports before publication. Hand found items to the school desk.</p><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="report"><input type="hidden" name="submission_key" value="<?= bin2hex(random_bytes(16)) ?>"><label for="lf-kind">Report type</label><select id="lf-kind" name="kind" class="form-select"><option>Lost</option><option>Found</option></select><label for="lf-category">Item category</label><select id="lf-category" name="category" class="form-select"><?php foreach(LOST_FOUND_CATEGORIES as $cat): ?><option><?= e($cat) ?></option><?php endforeach; ?></select><label>Generic item title<input name="title" class="form-control" minlength="3" maxlength="100" required></label><label>Broad location<input name="location" class="form-control" minlength="2" maxlength="120" required></label><label>Date lost or found<input type="date" name="item_date" class="form-control" max="<?= date('Y-m-d') ?>" value="<?= date('Y-m-d') ?>" required></label><label>Private identifying details<textarea name="private_details" class="form-control" rows="4" minlength="5" maxlength="1500" required></textarea></label><button class="btn btn-primary">Submit report for review</button></form></section></div>
<div class="col-lg-7"><section class="panel"><h2>Search campus listings</h2><form method="get" class="campus-form"><label>Search item or broad location<input name="q" class="form-control" maxlength="120" value="<?= e($q) ?>"></label><label for="lf-filter-kind">Report type filter</label><select id="lf-filter-kind" name="kind" class="form-select"><option value="">Lost and found</option><?php foreach(['Lost','Found'] as $k): ?><option <?= $kind===$k?'selected':'' ?>><?= $k ?></option><?php endforeach; ?></select><label for="lf-filter-category">Category filter</label><select id="lf-filter-category" name="category" class="form-select"><option value="">All categories</option><?php foreach(LOST_FOUND_CATEGORIES as $cat): ?><option <?= $category===$cat?'selected':'' ?>><?= e($cat) ?></option><?php endforeach; ?></select><label>From date<input type="date" name="after" value="<?= e($after) ?>" class="form-control"></label><label>To date<input type="date" name="before" value="<?= e($before) ?>" class="form-control"></label><button class="btn btn-outline-primary">Search listings</button></form><?php if(!$listings)empty_state('No matching open listings');foreach($listings as $listing): ?><article class="campus-event"><a href="?id=<?= (int)$listing['id'] ?>"><?= e($listing['title']) ?></a><p><?= e($listing['kind'].' · '.$listing['category'].' · '.$listing['item_date'].' · '.$listing['location']) ?></p></article><?php endforeach; ?></section></div></div>
<section class="panel"><h2><?= $staff?'School reports & moderation':'My reports' ?></h2><?php foreach(rows('SELECT id,title,listing_state,resolution FROM lost_found_items '.($staff?'':'WHERE owner_id='.(int)$u['id']).' ORDER BY id DESC LIMIT 100') as $report): ?><article class="campus-event"><a href="?id=<?= (int)$report['id'] ?>"><?= e($report['title'].' · '.$report['listing_state'].' · '.$report['resolution']) ?></a></article><?php endforeach; ?></section>
<section class="panel"><h2>My private claims</h2><?php foreach(rows('SELECT c.id,c.state,i.title FROM lost_found_claims c JOIN lost_found_items i ON i.id=c.item_id WHERE c.owner_id=? ORDER BY c.id DESC LIMIT 100',[$u['id']]) as $c): ?><article class="campus-event"><a href="?claim=<?= (int)$c['id'] ?>"><?= e($c['title'].' · '.$c['state']) ?></a></article><?php endforeach; ?></section>
<?php endif;render_footer(); ?>
